// "estimate". Facade rhythms, podium heights and crowns are read from photographs and are approximate.
const TWR = (c, k) => ({m:1, c:c || '#e6efff', k:k || 0.6});
// generic tower: podium (optional, plan podP), shaft (plan T) with glass / bands / fins, crown (louvred plant screen or steps)
function gTower(B, d, o){
  const P = o.P || d.o, T = o.T || P, pod = o.pod || 0;
  fndP(B, OUT(o.podP || P, 0.05), d);
  if (pod > 0) podP(B, o.podP || P, 0.3, pod, o.po);
  const y0 = pod > 0 ? pod - 0.5 : 0.3, yc = o.yc || o.h - (o.ch || 6);
  cwP(B, T, y0, yc, o);
  if (pod <= 0) floorsP(B.p(LOBBY), T, 0.5, 6.0, 99, 5.2, 0.08);
  if (o.steps){ const top = stepsP(B, T, yc, o.steps, o.sc || ALU2, o.se || WHT); flatP(B.p(ROOF), IN(T, o.steps.reduce((m, s) => Math.max(m, s[0]), 0)), top + 0.02); aviP(B, IN(T, o.steps[o.steps.length - 1][0]), top); }
  else crownP(B, T, yc, o.h - yc, o.cr);
  return {P, T, yc};
}
const terr = (B, P, y, col) => { flatP(B.p(col || GRN), IN(P, 0.6), y + 0.06); parP(B.p(STN('#d6d2c8', 0.35)), P, y, 1.1, 0.3); };

