// NEC Supertower (1990; 180 m, 44 floors). OSM w87510456 with the map's records w497184150 (tower slab 68 x 38 m) and w497184145 /
// w497184149 (the 38 m / 12-level wings either side — OSM tags). Wide lower body (tower slab + wings), the open "wind gap" through
// the slab above the wings, the upper shaft, and the stepped "rocket" top in three tiers. Gap height and tier sizes are estimates.
defT('tynec', 'NEC Supertower', 'NEC Supertower', 180, 66, TWR(), (B, d) => {
  const P = d.o, T = d.rec.w497184150, Wn = d.rec.w497184149, Ws = d.rec.w497184145, ob = obE(T), hu = ob.L/2, hv = ob.W/2;
  const SK = STN('#c6c9cb', 0.35), GD = GL('#5f6f79');
  fndP(B, P, d);
  podP(B, P, 0.3, 12, {w:STN('#bfbcb5'), wg:GD, fh:4.2, gh:2.4, lob:6});
  for (const W of [Wn, Ws]){ prismP(B.p(SK), W, 12, 38, true); floorsP(B.p(GD), W, 12.6, 37, 3.6, 2.0, 0.06); prismP(B.p(WHT), OUT(W, 0.2), 37.4, 38.4, true); flatP(B.p(ROOF2), W, 38.05); }
  const yG0 = 38, yG1 = 50;
  prismP(B.p(SK), T, 12, yG0, true); floorsP(B.p(GD), T, 12.6, yG0 - 0.6, 3.6, 2.0, 0.06);
  // the wind gap: a void across the slab between two solid end blocks, with a few columns
  for (const s of [-1, 1]){ const E = ob.rect(s < 0 ? -hu : hu - 14, s < 0 ? -hu + 14 : hu, -hv, hv); prismP(B.p(SK), E, yG0, yG1, true); }
  flatP(B.p(SK), T, yG0 + 0.05); flatP(B.p(dsS(SK)), T, yG1 - 0.05);
  for (const u of [-10, 0, 10]) for (const v of [-hv + 6, hv - 6]){ const q = ob.p(u, v); boxP(B.p(SK), 1.6, yG1 - yG0, 1.6, q[0], yG0, q[1], ob.ry); }
  prismP(B.p(SK), T, yG1, 150, true); floorsP(B.p(GD), T, yG1 + 0.6, 149.4, 3.6, 2.1, 0.06); mullP(B.p(WHT), T, yG1, 150, 6.4, 0.5, 0.05, null, 0.4);
  // the stepped top: three tiers narrowing toward the long sides
  let y = 150; for (const [du, dv, h] of [[3, 3.5, 11], [7, 8, 10], [12, 12.5, 9]]){ const Q = ob.rect(-hu + du, hu - du, -hv + dv, hv - dv); prismP(B.p(SK), Q, y, y + h); floorsP(B.p(GD), Q, y + 0.6, y + h - 0.8, 3.6, 2.0, 0.06); prismP(B.p(WHT), OUT(Q, 0.2), y + h - 0.6, y + h + 0.1, true); y += h; }
  aviP(B, ob.rect(-hu + 12, hu - 12, -hv + 12.5, hv - 12.5), y);
});

